using System.Collections.Generic;
using System.Text;
using TMPro;
using TurnTheDial.Core.Combat;
using TurnTheDial.Core.Content;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

namespace TurnTheDial.Game.ProtoCombat
{
    /// <summary>
    /// A card box: name, cost, type line and rules text generated by Core from data. Left click or
    /// Submit (Enter / A) plays it; right click cues it (mouse cue path). Its tooltip lists every keyword it has, the Reach it would deal
    /// now with the math, and why it can't be played.
    /// </summary>
    [RequireComponent(typeof(Button), typeof(TooltipSource))]
    public sealed class CardView : MonoBehaviour, IPointerClickHandler, IPointerEnterHandler, IPointerExitHandler
    {
        [SerializeField] private TMP_Text title;
        [SerializeField] private TMP_Text meta;
        [SerializeField] private TMP_Text rules;
        [SerializeField] private Image background;
        [SerializeField] private Button button;
        [SerializeField] private TooltipSource tooltip;
        [SerializeField] private Color playableColor = new Color(0.20f, 0.22f, 0.27f);
        [SerializeField] private Color unplayableColor = new Color(0.13f, 0.13f, 0.15f);
        [SerializeField] private Color textColor = new Color(0.96f, 0.93f, 0.85f);
        [SerializeField] private Color dimTextColor = new Color(0.60f, 0.58f, 0.54f);

        private ProtoCombatController _controller;

        /// <summary>The card under the mouse pointer, if any (C cues it).</summary>
        public static CardView Hovered { get; private set; }

        public int Uid { get; private set; } = -1;

        public bool InCueSlot { get; private set; }

        private void Awake()
        {
            button.onClick.AddListener(OnClick);
        }

        public void Bind(ProtoCombatController controller, Fight fight, CardInstance inst, bool inCueSlot)
        {
            _controller = controller;
            InCueSlot = inCueSlot;
            if (inst == null)
            {
                Uid = -1;
                title.text = "Cue slot";
                meta.text = "empty";
                rules.text = "Right-click a card, or press C / X, to cue it.";
                background.color = unplayableColor;
                SetTextColor(dimTextColor);
                tooltip.Text = Glossary.TermText(Term.CueSlot, fight.Balance);
                return;
            }

            Uid = inst.Uid;
            CardData c = inst.Card;
            bool playable = fight.CanPlay(inst.Uid, out string reason);
            title.text = c.DisplayName + (inCueSlot ? "  (cued)" : "");
            meta.text = "Cost " + c.Cost + " · " + CardTextGenerator.TypeLine(c);
            rules.text = CardTextGenerator.RulesText(c, fight.Catalog);
            background.color = playable ? playableColor : unplayableColor;
            SetTextColor(playable ? textColor : dimTextColor);
            tooltip.Text = BuildTooltip(fight, inst, playable, reason);
        }

        private static string BuildTooltip(Fight fight, CardInstance inst, bool playable, string reason)
        {
            CardData c = inst.Card;
            var sb = new StringBuilder();
            sb.Append("<b>").Append(c.DisplayName).Append("</b>  Cost ").Append(c.Cost).Append(" · ").Append(CardTextGenerator.TypeLine(c)).Append('\n');
            sb.Append(CardTextGenerator.RulesText(c, fight.Catalog));
            int reach = fight.PreviewReach(inst.Uid, out string math);
            if (math != null)
            {
                sb.Append("\nIf played now: ").Append(math).Append(" (before Lock ").Append(fight.Lock).Append(").");
            }

            List<Keyword> keywords = CardTextGenerator.KeywordsOf(c);
            for (int i = 0; i < keywords.Count; i++)
            {
                sb.Append("\n- ").Append(Glossary.KeywordText(keywords[i], fight.Balance));
            }

            if (c.IsSong && FindBurnout(fight, c.Name))
            {
                sb.Append("\n- ").Append(Glossary.TermText(Term.Burnout, fight.Balance));
            }

            if (!playable && reason != null)
            {
                sb.Append("\n<i>Can't play: ").Append(reason).Append("</i>");
            }

            return sb.ToString();
        }

        private static bool FindBurnout(Fight fight, string name)
        {
            for (int i = 0; i < fight.Burnout.Count; i++)
            {
                if (fight.Burnout[i].Name == name) return true;
            }

            return false;
        }

        private void SetTextColor(Color color)
        {
            title.color = color;
            meta.color = color;
            rules.color = color;
        }

        public void OnPointerClick(PointerEventData eventData)
        {
            // Button handles the left click (play). Right click cues a hand card.
            if (eventData.button != PointerEventData.InputButton.Right) return;
            if (_controller == null || Uid < 0 || InCueSlot) return;
            _controller.Cue(Uid);
        }

        public void OnPointerEnter(PointerEventData eventData) => Hovered = this;

        public void OnPointerExit(PointerEventData eventData)
        {
            if (Hovered == this) Hovered = null;
        }

        private void OnDisable()
        {
            if (Hovered == this) Hovered = null;
        }

        private void OnClick()
        {
            if (_controller == null || Uid < 0) return;
            _controller.PlayCard(Uid);
        }
    }
}
